use omoikane::dom::NodeHandle;
use omoikane::js::{JsRuntime, SandboxConfig};
use std::time::Duration;

#[inline(never)]
#[unsafe(no_mangle)]
fn profile_loop(runtime: &mut JsRuntime, expression: &str) -> f64 {
    runtime.eval(expression).unwrap().as_number().unwrap()
}

fn main() {
    let args: Vec<_> = std::env::args().collect();
    let shape = args.get(1).expect("shape");
    let n: u64 = args.get(2).expect("iteration count").parse().unwrap();
    assert!(n <= 500_000);
    let jit = args.get(3).expect("on/off") == "on";
    let expected = match shape.as_str() {
        "primitive-string-property" => (3*n) % 1_000_003,
        "string-concat" => 2*(n % 2049),
        _ => panic!("unsupported diagnostic workload"),
    };
    let mut runtime = JsRuntime::with_document_and_sandbox(
        NodeHandle::document(),
        SandboxConfig {
            max_loop_iterations: 100_000_000,
            // Only this standalone instrumented diagnostic uses a long timeout.
            timeout: Duration::from_secs(3600),
        },
    ).unwrap();
    runtime.set_baseline_jit_enabled(jit);
    runtime.eval(include_str!("/tmp/omoikane-issue659/tests/js_benchmark/history/shapes-v1.js")).unwrap();
    runtime.eval("var __profileBodies = {}; bench = function(name, iterations, body) { __profileBodies[name] = body; return name; }; runBenchmarks();").unwrap();
    let expression = format!("__profileBodies['{shape}']({n})");
    let actual = profile_loop(&mut runtime, &expression);
    assert_eq!(actual, expected as f64);
    println!("shape={shape} iterations={n} expected={expected} actual={actual} jit={jit}");
    println!("diagnostics={:?}", runtime.baseline_jit_diagnostics());
}

