+
+#[test]
+fn runtime_cache_preserves_warmup_reuse_and_fifo_eviction() {
+    fn block(context: &mut Context) -> boa_gc::Rooted<CodeBlock> {
+        crate::Script::parse(Source::from_bytes("({ value: 42 }).value"), None, context)
+            .unwrap()
+            .codeblock(context)
+            .unwrap()
+    }
+    let mut context = Context::default();
+    let first = block(&mut context);
+    let mut runtime = VmRuntime::default();
+    for _ in 0..7 {
+        assert!(runtime.code(&first).is_none());
+    }
+    let compiled = runtime.code(&first).expect("eighth entry compiles");
+    for _ in 0..32 {
+        assert!(Rc::ptr_eq(&compiled, &runtime.code(&first).unwrap()));
+    }
+    // Each parsed block has its own identity even for identical source text.
+    let others: Vec<_> = (0..255).map(|_| block(&mut context)).collect();
+    for other in &others {
+        assert_ne!(first.jit_code_id, other.jit_code_id);
+        assert!(runtime.code(other).is_none());
+    }
+    assert_eq!(runtime.cache.len(), 256);
+    // Hits reuse the compiled entry without refreshing FIFO insertion order.
+    assert!(Rc::ptr_eq(&compiled, &runtime.code(&first).unwrap()));
+    assert_eq!(runtime.insertion_order.front(), Some(&first.jit_code_id));
+    let next = block(&mut context);
+    assert!(runtime.code(&next).is_none());
+    assert_eq!(runtime.cache.len(), 256);
+    assert_eq!(runtime.insertion_order.len(), 256);
+    assert!(!runtime.cache.contains_key(&first.jit_code_id));
+    assert_eq!(
+        runtime.insertion_order.front(),
+        Some(&others[0].jit_code_id)
+    );
+    // A live owner still keeps an evicted code mapping and its metadata alive.
+    assert!(!compiled.entries.is_empty());
+    assert_eq!(
+        compiled.entries.len(),
+        compiled.descriptor.safepoints().len()
+    );
+    assert!(runtime.code(&first).is_none());
+    assert_eq!(runtime.cache.len(), 256);
+    assert!(!runtime.cache.contains_key(&others[0].jit_code_id));
+}
